// Checks for saving and protection: the local server keeps events in plain files, one per person, gives each
// person back only their own, queues sealed messages to a doctor, refuses other sites and other host names,
// never serves private folders, and sends its security headers. The rules themselves are in src/security.js.
// Run: npm test (Node 18+). Uses a throwaway data folder, never the real one.
// Code generated by Claude (Anthropic), an AI system.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { createHash } from 'node:crypto';
import { request } from 'node:http';
import { mkdir, mkdtemp, readdir, readFile, realpath, rm, rmdir, stat, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join, sep } from 'node:path';
import { fileURLToPath } from 'node:url';
import {
  LIMITS, SECURITY_RULES, allowedHosts, cleanEvent, contentSecurityPolicy, eventProblem, hostName, isJson, isPrivatePath, sameOrigin, siteAllowed,
} from '../src/security.js';
import { CREW, SOURCES } from '../src/config.js';
import { exampleFlight } from '../src/demo-crew.js';
import { openMessage } from '../tools/read-outbox.mjs';

const APP = fileURLToPath(new URL('..', import.meta.url));
const DEMO_KEY = join(APP, 'demo-keys', 'DEMO-flight-surgeon-keypair.json');

async function startServer(dataDir, env = {}) {
  const port = 20000 + Math.floor(Math.random() * 20000);
  const child = spawn(process.execPath, ['serve.mjs'], { cwd: APP, env: { ...process.env, HOSTS: '', OUTBOX_KEY_FILE: '', ...env, PORT: String(port), DATA_DIR: dataDir }, stdio: ['ignore', 'pipe', 'pipe'] });
  await new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error('server did not start')), 5000);
    child.stdout.on('data', (d) => { if (String(d).includes('running')) { clearTimeout(timer); resolve(); } });
    child.on('exit', (code) => { clearTimeout(timer); reject(new Error(`server exited ${code}`)); });
  });
  return { base: `http://127.0.0.1:${port}`, port, stop: () => child.kill() };
}

// Runs a check against a fresh server with its own throwaway data folder, and always cleans up.
async function withServer(fn, env) {
  const dir = await mkdtemp(join(tmpdir(), 'jff-data-'));
  const srv = await startServer(dir, env);
  try {
    await fn(srv, dir);
  } finally {
    srv.stop();
    await rm(dir, { recursive: true, force: true });
  }
}

// A plain HTTP request with full control of the headers (fetch does not let a program set Host).
function raw(srv, path, { method = 'GET', headers = {}, body } = {}) {
  return new Promise((resolve, reject) => {
    const own = Object.keys(headers).some((k) => k.toLowerCase() === 'host');
    const req = request({ host: '127.0.0.1', port: srv.port, path, method, headers, setHost: !own }, (res) => {
      const chunks = [];
      res.on('data', (c) => chunks.push(c));
      res.on('end', () => resolve({ status: res.statusCode, headers: res.headers, text: Buffer.concat(chunks).toString('utf8') }));
    });
    req.on('error', reject);
    if (body !== undefined) req.write(body);
    req.end();
  });
}

const minutes = (n) => new Date(Date.now() + n * 60 * 1000).toISOString();
const SWITCHES = { aiWorks: true, doctorOnBoard: false, linkToEarth: true };
const event = (person, value, time, indicator = 'pulse', source = 'pulse-meter') => ({
  v: 1, kind: 'reading', time, person, state: SWITCHES, reading: { source, indicator, value },
});
const report = (person, text, time = minutes(-1), to = 'doctor-earth') => ({ v: 1, kind: 'report', time, person, state: SWITCHES, report: { to, text } });
const postJson = (srv, value, headers = {}) => raw(srv, '/api/events', { method: 'POST', headers: { 'Content-Type': 'application/json', ...headers }, body: typeof value === 'string' ? value : JSON.stringify(value) });
const getJson = async (srv, path) => {
  const r = await raw(srv, path);
  return { status: r.status, value: r.status === 200 ? JSON.parse(r.text) : null };
};
const filesIn = async (dir) => { try { return (await readdir(dir)).sort(); } catch { return []; } };

test('saved events come back, in time order, and live in one plain file per person named by id', async () => {
  await withServer(async (srv, dir) => {
    assert.equal((await postJson(srv, event('crew-1', 80, '2026-03-02T08:00:00.000Z'))).status, 204);
    assert.equal((await postJson(srv, event('crew-1', 70, '2026-03-01T08:00:00.000Z'))).status, 204);
    assert.equal((await postJson(srv, event('crew-2', 65, '2026-03-01T09:00:00.000Z'))).status, 204);
    const back = (await getJson(srv, '/api/events?all=1')).value;
    assert.deepEqual(back.map((e) => e.reading.value), [70, 65, 80]);
    assert.deepEqual(await filesIn(dir), ['crew-1.jsonl', 'crew-2.jsonl']);
    const lines = (await readFile(join(dir, 'crew-1.jsonl'), 'utf8')).trim().split('\n');
    assert.equal(lines.length, 2);
  });
});

