test('saving takes only application/json, so a plain web form or text/plain request from another site gets nowhere', async () => {
  await withServer(async (srv, dir) => {
    const body = JSON.stringify(event('crew-1', 70, minutes(-1)));
    for (const type of ['text/plain', 'text/plain;charset=UTF-8', 'application/x-www-form-urlencoded', 'multipart/form-data; boundary=x', undefined]) {
      const headers = type ? { 'Content-Type': type } : {};
      assert.equal((await raw(srv, '/api/events', { method: 'POST', headers, body })).status, 415, String(type));
    }
    assert.equal((await raw(srv, '/api/events', { method: 'POST', headers: { 'Content-Type': 'application/json; charset=utf-8' }, body })).status, 204);
    assert.deepEqual(await filesIn(dir), ['crew-1.jsonl']);
    const big = JSON.stringify(report('crew-1', 'x'.repeat(LIMITS.bodyBytes)));
    assert.equal((await postJson(srv, big)).status, 413);
  });
});

test('saving from another site is refused; this program\'s own page and plain programs may save', async () => {
  await withServer(async (srv, dir) => {
    const e = event('crew-1', 70, minutes(-1));
    const own = `http://127.0.0.1:${srv.port}`;
    for (const headers of [
      { Origin: 'http://evil.example' },
      { Origin: 'null' },
      { Origin: `http://localhost:${srv.port}` }, // another origin than the page's own, even on this computer
      { Origin: 'http://127.0.0.1:1' },
      { Origin: own, 'Sec-Fetch-Site': 'cross-site' },
      { Origin: own, 'Sec-Fetch-Site': 'same-site' },
      { 'Sec-Fetch-Site': 'none' },
    ]) assert.equal((await postJson(srv, e, headers)).status, 403, JSON.stringify(headers));
    assert.deepEqual(await filesIn(dir), []);
    assert.equal((await postJson(srv, e, { Origin: own, 'Sec-Fetch-Site': 'same-origin' })).status, 204, 'the page itself');
    assert.equal((await postJson(srv, e)).status, 204, 'curl or a test: no Origin');
    assert.equal((await raw(srv, '/api/events?person=crew-1', { headers: { 'Sec-Fetch-Site': 'cross-site' } })).status, 403, 'no reading from another site either');
    assert.equal((await raw(srv, '/api/events?person=crew-1', { headers: { 'Sec-Fetch-Site': 'none' } })).status, 200, 'an address typed by hand may read');
    assert.equal((await raw(srv, '/api/events', { method: 'OPTIONS', headers: { Origin: 'http://evil.example' } })).status, 405, 'no CORS preflight is ever granted');
  });
});

