test('every response carries the security headers; the page\'s own inline script is allowed by its hash', async () => {
  await withServer(async (srv) => {
    const page = await raw(srv, '/');
    assert.equal(page.status, 200);
    const csp = page.headers['content-security-policy'];
    for (const part of [
      "default-src 'self'", "style-src 'self' 'unsafe-inline'", "img-src 'self' data: blob:", "media-src 'self' blob:", "worker-src 'self' blob:",
      "connect-src 'self' https://services.swpc.noaa.gov https://kauai.ccmc.gsfc.nasa.gov https://osdr.nasa.gov https://visualization.osdr.nasa.gov https://api.nasa.gov",
      "object-src 'none'", "base-uri 'self'", "frame-ancestors 'none'",
    ]) assert.ok(csp.includes(part), part);
    assert.match(csp, /script-src 'self' 'wasm-unsafe-eval'/);
    assert.doesNotMatch(csp, /'unsafe-eval'|script-src[^;]*'unsafe-inline'/);
    // The hash the browser will compute: the inline script's text with CR LF turned into LF.
    const html = await readFile(join(APP, 'index.html'), 'utf8');
    const inline = [...html.matchAll(/<script>([\s\S]*?)<\/script>/g)].map((m) => createHash('sha256').update(m[1].replace(/\r\n?/g, '\n')).digest('base64'));
    assert.ok(inline.length >= 1, 'index.html has its theme script inline');
    for (const h of inline) assert.ok(csp.includes(`'sha256-${h}'`), 'inline script hash');
    for (const path of ['/', '/src/crew.js', '/vendor/mediapipe/wasm/vision_wasm_internal.wasm', '/api/events?person=crew-1', '/no-such-file', '/data/x']) {
      const r = await raw(srv, path);
      assert.equal(r.headers['referrer-policy'], 'no-referrer', path);
      assert.equal(r.headers['x-content-type-options'], 'nosniff', path);
      assert.equal(r.headers['x-frame-options'], 'DENY', path);
      assert.equal(r.headers['cross-origin-resource-policy'], 'same-origin', path);
      assert.match(r.headers['permissions-policy'], /^camera=\(self\), bluetooth=\(self\), microphone=\(\)/, path);
      assert.match(r.headers['content-security-policy'], /frame-ancestors 'none'/, path);
    }
    assert.equal((await raw(srv, '/vendor/mediapipe/wasm/vision_wasm_internal.wasm')).headers['content-type'], 'application/wasm');
    assert.equal((await raw(srv, '/api/events?person=crew-1')).headers['cache-control'], 'no-store');
  });
});

test('a message to a doctor is queued in data/outbox, sealed so that only the flight surgeon\'s key opens it', async () => {
  await withServer(async (srv, dir) => {
    const text = 'Chest feels tight since this morning. Mood low.';
    const sent = await postJson(srv, report('crew-1', text));
    assert.equal(sent.status, 201);
    const { outbox } = JSON.parse(sent.text);
    assert.equal(outbox.status, 'queued');
    assert.equal(outbox.encrypted, true);
    assert.equal(outbox.demoKey, true);
    const files = await filesIn(join(dir, 'outbox'));
    assert.deepEqual(files, [`${outbox.id}.json`]);
    assert.match(files[0], /^\d{8}T\d{6,9}Z-[0-9a-f]{8}\.json$/, 'time and a random number: no personal information in the name');
    const stored = await readFile(join(dir, 'outbox', files[0]), 'utf8');
    assert.ok(!stored.includes('Chest') && !stored.includes('Mood'), 'the text is not readable in the file');
    const entry = JSON.parse(stored);
    assert.equal(entry.to, 'doctor-earth');
    assert.equal(entry.person, 'crew-1');
    assert.equal(entry.status, 'queued');
    assert.equal(typeof entry.time, 'string');
    assert.equal(entry.body.alg, 'ECDH-ES P-256 + HKDF-SHA-256 + AES-256-GCM');
    // The ground side opens it with the private key (a separate program, tools/read-outbox.mjs).
    const key = JSON.parse(await readFile(DEMO_KEY, 'utf8'));
    assert.equal(openMessage(entry, key.privateJwk), text);
    // Changing who it is from, or the sealed text, breaks the seal.
    assert.throws(() => openMessage({ ...entry, person: 'crew-2' }, key.privateJwk));
    assert.throws(() => openMessage({ ...entry, body: { ...entry.body, ciphertext: entry.body.ciphertext.replace(/^./, (c) => (c === 'A' ? 'B' : 'A')) } }, key.privateJwk));
    // The person's own file keeps the message, so the screen can show what was sent.
    const own = (await getJson(srv, '/api/events?person=crew-1')).value;
    assert.equal(own.filter((e) => e.kind === 'report')[0].report.text, text);
    // The screen can list what waits for the downlink, without the text.
    const list = (await getJson(srv, '/api/outbox?person=crew-1')).value;
    assert.equal(list.length, 1);
    assert.equal(list[0].id, outbox.id);
    assert.equal(list[0].body, undefined);
    assert.deepEqual((await getJson(srv, '/api/outbox?person=crew-2')).value, []);
    assert.equal((await getJson(srv, '/api/outbox?all=1')).value.length, 1);
    assert.equal((await raw(srv, '/api/outbox')).status, 400);
    assert.equal((await raw(srv, '/api/outbox', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' })).status, 405);
  });
});

test('without a key the message is not queued and not kept, so the screen can say so and send it again', async () => {
  await withServer(async (srv, dir) => {
    assert.equal((await postJson(srv, report('crew-1', 'hello'))).status, 503);
    assert.deepEqual(await filesIn(dir), []);
    assert.equal((await postJson(srv, event('crew-1', 70, minutes(-1)))).status, 204, 'readings still save');
  }, { OUTBOX_KEY_FILE: join(APP, 'demo-keys', 'no-such-key.json') });
});

test('without a key a message to the doctor on board is still kept (that doctor reads it here); one to Earth is refused', async () => {
  await withServer(async (srv, dir) => {
    assert.equal((await postJson(srv, report('crew-1', 'Can you look at my ankle?', minutes(-1), 'doctor-onboard'))).status, 204);
    assert.deepEqual(await filesIn(join(dir, 'outbox')), []);
    const own = (await getJson(srv, '/api/events?person=crew-1')).value;
    assert.equal(own[0].report.to, 'doctor-onboard');
    assert.equal((await postJson(srv, report('crew-1', 'And this one to Earth.'))).status, 503, 'a message to Earth needs the key');
  }, { OUTBOX_KEY_FILE: join(APP, 'demo-keys', 'no-such-key.json') });
  await withServer(async (srv, dir) => {
    const r = await postJson(srv, report('crew-1', 'Can you look at my ankle?', minutes(-1), 'doctor-onboard'));
    assert.equal(r.status, 201, 'with a key it is queued too, as before');
    assert.equal(JSON.parse(r.text).outbox.to, 'doctor-onboard');
    assert.equal((await filesIn(join(dir, 'outbox'))).length, 1);
  });
});

// The static copy (GitHub Pages) gets no headers, so a page may carry the policy in a meta tag. That copy of the
// policy must name the hash of each inline script, or the page's own script stops working there and here.
test('a page that carries its own Content-Security-Policy meta tag allows its inline scripts by hash', async () => {
  for (const page of ['index.html', 'machine.html']) {
    const html = await readFile(join(APP, page), 'utf8');
    const tag = [...html.matchAll(/<meta\b[^>]*>/gi)].map((m) => m[0]).find((m) => /http-equiv\s*=\s*["']?Content-Security-Policy/i.test(m));
    if (!tag) continue; // no meta tag: the server's header is the only policy
    const policy = (/content\s*=\s*"([^"]*)"/i.exec(tag) || [])[1] || '';
    assert.doesNotMatch(policy, /script-src[^;]*'unsafe-inline'/, page);
    for (const m of html.matchAll(/<script\b([^>]*)>([\s\S]*?)<\/script\s*>/gi)) {
      if (/\bsrc\s*=/i.test(m[1])) continue;
      const hash = createHash('sha256').update(m[2].replace(/\r\n?/g, '\n'), 'utf8').digest('base64');
      assert.ok(policy.includes(`'sha256-${hash}'`), `${page}: the meta policy must name 'sha256-${hash}'`);
    }
  }
});

// ---------- the rules themselves (src/security.js) ----------
test('host names: parsing and the allowed list', () => {
  assert.equal(hostName('127.0.0.1:8080'), '127.0.0.1');
  assert.equal(hostName('LocalHost:8080'), 'localhost');
  assert.equal(hostName('[::1]:8080'), '[::1]');
  assert.equal(hostName('[::1]'), '[::1]');
  for (const bad of [undefined, '', 'evil.example:80:80', 'a b', 'x'.repeat(300), 'user@host', 'host/path']) assert.equal(hostName(bad), '', String(bad));
  assert.deepEqual([...allowedHosts()].sort(), ['127.0.0.1', '[::1]', 'localhost']);
  assert.ok(allowedHosts({ host: '192.168.1.5' }).has('192.168.1.5'));
  assert.ok(!allowedHosts({ host: '0.0.0.0' }).has('0.0.0.0'), 'listening everywhere names no host');
  const more = allowedHosts({ hosts: 'Crew-Laptop.local, fe80::1 ,, 10.0.0.5:8080' });
  for (const h of ['crew-laptop.local', '[fe80::1]', '10.0.0.5']) assert.ok(more.has(h), h);
});

test('private names, origins, fetch metadata and content types', () => {
  for (const p of ['data/x.jsonl', 'DATA\\x', 'Data. /x', 'tests/a.js', 'TOOLS', 'node_modules/a', 'Brainstorm/IDEA.md', 'demo-keys/k.json', '.git', '.GIT/HEAD', '.env', 'src/.hidden', 'vendor/.cache/x']) {
    assert.equal(isPrivatePath(p), true, p);
  }
  for (const p of ['index.html', 'src/store.js', 'vendor/mediapipe/NOTICE.md', 'fonts/fonts.css', 'docs/SECURITY.md', 'database.html', 'src/data.js', '']) assert.equal(isPrivatePath(p), false, p);
  assert.equal(sameOrigin(undefined, '127.0.0.1:8080'), true);
  assert.equal(sameOrigin('http://127.0.0.1:8080', '127.0.0.1:8080'), true);
  assert.equal(sameOrigin('HTTP://LOCALHOST:8080', 'localhost:8080'), true);
  assert.equal(sameOrigin('http://localhost:8080', '127.0.0.1:8080'), false);
  assert.equal(sameOrigin('null', '127.0.0.1:8080'), false);
  assert.equal(siteAllowed(undefined, 'POST'), true);
  assert.equal(siteAllowed('same-origin', 'POST'), true);
  assert.equal(siteAllowed('none', 'GET'), true);
  for (const [v, m] of [['none', 'POST'], ['same-site', 'GET'], ['cross-site', 'POST'], ['cross-site', 'GET']]) assert.equal(siteAllowed(v, m), false, `${v} ${m}`);
  assert.equal(isJson('application/json'), true);
  assert.equal(isJson('Application/JSON; charset=utf-8'), true);
  for (const t of [undefined, '', 'text/plain', 'application/jsonx', 'application/x-www-form-urlencoded', 'text/plain; application/json']) assert.equal(isJson(t), false, String(t));
});

test('crew alarms reach every crewmate, without the rest of the record', async () => {
  await withServer(async (srv) => {
    const t = minutes(-10);
    assert.equal((await postJson(srv, event('crew-2', 75, t))).status, 204);
    assert.equal((await postJson(srv, { v: 1, kind: 'alarm', time: t, person: 'crew-2', alarm: { text: 'Elly needs help now: Oxygen saturation 85 %.' } })).status, 204);
    const got = (await getJson(srv, '/api/events?person=crew-1')).value;
    assert.deepEqual(got.map((e) => `${e.person}:${e.kind}`), ['crew-2:alarm'], 'only the alarm line of crew-2');
    assert.equal((await postJson(srv, { v: 1, kind: 'alarm', time: t, person: 'crew-2', alarm: { text: 'x', extra: 1 } })).status, 400);
    assert.equal((await postJson(srv, { v: 1, kind: 'alarm', time: t, person: 'crew-2', alarm: { text: 'x'.repeat(201) } })).status, 400);
  });
});

test('the new answers are kept in their checked shapes, and nothing else', () => {
  const now = Date.parse('2026-11-15T12:00:00.000Z');
  const t = '2026-11-15T11:00:00.000Z';
  const rd = (indicator, value, extra = {}) => ({ v: 1, kind: 'reading', time: t, person: 'crew-1', reading: { source: 'x', indicator, value, ...extra } });
  assert.equal(eventProblem(rd('weighing', ['home', 'crew']), { now }), null);
  assert.match(eventProblem(rd('weighing', ['home', 'home']), { now }), /topics/);
  assert.match(eventProblem(rd('weighing', ['party']), { now }), /topics/);
  assert.equal(eventProblem(rd('symptoms', { symptom: 'headache', severity: 4 }), { now }), null);
  assert.match(eventProblem(rd('symptoms', { symptom: 'headache', severity: 11 }), { now }), /symptom/);
  assert.equal(eventProblem(rd('medicines', { medicine: 'ibuprofen', amount: 1 }), { now }), null);
  assert.match(eventProblem(rd('medicines', { medicine: 'unknown', amount: 1 }), { now }), /medicine/);
  assert.deepEqual(cleanEvent(rd('symptoms', { symptom: 'headache', severity: 4, junk: 'x'.repeat(50) })).reading.value, { symptom: 'headache', severity: 4 });
  assert.equal(eventProblem(rd('pulse', 150, { context: 'exercise' }), { now }), null);
  assert.match(eventProblem(rd('pulse', 150, { context: 'sleep' }), { now }), /exercise/);
  const detail = { median: 301, lapses: 1, falseStarts: 0, count: 60, durationS: 180, mode: 'full', score: 98 };
  assert.equal(eventProblem(rd('reaction', 301, { detail }), { now }), null);
  assert.match(eventProblem(rd('reaction', 301, { detail: { ...detail, trials: [] } }), { now }), /reaction test/);
  assert.match(eventProblem(rd('visionCheck', 'banana'), { now }), /answers/);
  assert.match(eventProblem(rd('pulse', 70, { detail }), { now }), /reaction test/);
  assert.deepEqual(cleanEvent(rd('reaction', 301, { detail })).reading.detail, detail);
});

test('the event check and the stored copy', () => {
  const now = Date.parse('2026-11-15T12:00:00.000Z');
  const e = event('crew-1', 70, '2026-11-15T12:04:00.000Z');
  assert.equal(eventProblem(e, { now }), null);
  assert.match(eventProblem({ ...e, time: '2026-11-15T12:06:00.000Z' }, { now }), /5 minutes ahead/);
  assert.equal(eventProblem({ ...e, time: '2026-11-15T12:06:00.000Z' }, { now, checkFuture: false }), null, 'reading back does not judge the clock again');
  assert.match(eventProblem({ ...e, time: '2026-11-15T25:00:00.000Z' }, { now }), /ISO 8601/);
  assert.deepEqual(cleanEvent({ ...e, state: { ...SWITCHES, extra: 1 } }), e);
});

test('every server rule names a real source and says whether it is a draft', () => {
  assert.ok(SECURITY_RULES.length >= 10);
  for (const r of SECURITY_RULES) {
    assert.ok(r.id && r.title && r.rule, r.id);
    assert.equal(typeof r.draft, 'boolean', r.id);
    assert.ok(r.sources.length >= 1, r.id);
    for (const s of r.sources) assert.match(s.url, /^https:\/\/[^\s]+$/, `${r.id}: ${s.name}`);
    assert.doesNotMatch(r.rule, /[\u2013\u2014]/, 'no long dashes');
  }
  assert.ok(SECURITY_RULES.find((r) => r.id === 'future-time').draft, 'the 5 minutes are a draft');
  assert.match(contentSecurityPolicy(['abc']), /script-src 'self' 'wasm-unsafe-eval' 'sha256-abc';/);
});
